    private static void DataLoads()
    {
        var sw = System.Diagnostics.Stopwatch.StartNew();
        var t = MappingTables.Load(DataLocator.Resolve(null));
        Expect.True(sw.ElapsedMilliseconds < 5000, $"loading took {sw.ElapsedMilliseconds} ms");
        Expect.Equal(244, t.Mapping.CultureProfileMap.Count);
        Expect.Equal(27, t.Mapping.Profiles.Count);
        Expect.Equal(111, t.MaaIndex.Count);
        Expect.Equal(1, t.MaaIndex["huscarl"]);
        Expect.True(t.Provinces.Count > 11000 && t.Climates.Count > 11000);
        Expect.Equal(17, t.Terrain.Terrain.Count);
        Expect.True(t.Terrain.Rules.Relief7Terciles.ContainsKey("hills"));
        Expect.Equal(2, t.Terrain.Weather.Ck3WinterOverride.Count);
        Expect.SequenceEqual(new[] { "6", "12", "15", "18", "22" }, t.Terrain.TimeOfDay.LegacyHours.Items.Select(kv => kv.Key));
        Expect.True(t.LoadableSceneIds.Contains("battle_terrain_029"));
        Expect.True(t.LoadableSceneIds.Contains("aserai_village_e"), "SandBoxCore village");
        Expect.False(t.LoadableSceneIds.Contains("aserai_village_d"), "SandBox is not in the normal launch (PROTOCOL §3.1)");
        Expect.True(t.Kits.ContainsKey("vla_king_template_bat_m"));
        Expect.True(t.IsSpawnableTroop("vlandian_recruit"));
        Expect.True(t.Ck3.MaaTypes.Count >= 111 && t.Ck3.Cultures.Count >= 244);
        Expect.Equal(5.0, t.Ck3.Terrains.Single(x => x.Key == "hills").DefenderAdvantage);
        Expect.Equal(25.0, t.Ck3.MaaTypes["bowmen"].Damage);
        Expect.Equal(27, t.Items["hauberk"].Armor!.Body);
        Expect.Equal(164, t.Knights.CombatTraits.Traits.Count);
        Expect.Equal(31, t.Knights.Accolades.Types.Count);
        Expect.Equal("linked_maa", t.Knights.Accolades.Types["archer_attribute"].Bannerlord.Captain.Rule);
        Expect.Equal("armor_mail", t.Knights.Artifacts.TypeToCategory["armor_mail"]);
        Expect.Equal("hauberk", t.Knights.Artifacts.Items["armor_mail"]["vlandia"]["common"]["foot"].Body);
        Expect.True(t.Restrictions.Rules.Count > 0, "restricted_troops loaded");
    }

    private static void EveryMaaResolves()
    {
        var t = Tables;
        var res = new TroopResolver(t.Mapping);
        int checkedCount = 0;
        foreach (var profile in t.Mapping.Profiles.Keys)
        foreach (var era in new[] { "culture_era_tribal", "culture_era_early_medieval", "culture_era_high_medieval", "culture_era_late_medieval" })
        {
            foreach (var key in t.Mapping.MaaTier.Keys)
            {
                var m = res.ResolveMaa(key, profile, era, null, null, null);
                if (m.Excluded) continue;
                Expect.True(m.Troops.Count > 0, $"{key}/{profile}/{era}: no troops");
                foreach (var tw in m.Troops) Expect.True(t.IsSpawnableTroop(tw.Troop), $"{key}/{profile}/{era}: {tw.Troop} not spawnable in CustomGame");
                Expect.True(m.AgentMultiplier is >= 0.5 and <= 2, $"{key}: multiplier {m.AgentMultiplier}");
                checkedCount++;
            }
            foreach (var nomadic in new[] { false, true })
                foreach (var tw in res.ResolveLevy(profile, era, nomadic).Troops) Expect.True(t.IsSpawnableTroop(tw.Troop), $"levy {profile}/{era}: {tw.Troop}");
            foreach (var tw in res.ResolveKnights(profile, era)) Expect.True(t.IsSpawnableTroop(tw.Troop), $"knights {profile}/{era}: {tw.Troop}");
        }
        Expect.True(checkedCount > 10000, $"only {checkedCount} combinations");
    }

    private static void EveryProvinceResolves()
    {
        var t = Tables;
        var resolver = new BattlefieldResolver(t);
        int n = 0;
        foreach (var id in t.Climates.Keys)
        {
            foreach (var month in new[] { 1, 7 })
            {
                var c = resolver.Resolve(new BattlefieldInput { ProvinceId = id, Year = 1066, Month = month, Day = 15, BattleSeq = id });
                Expect.True(t.LoadableSceneIds.Contains(c.Scene), $"province {id}: scene {c.Scene} missing");
                Expect.True(Seasons.Contains(c.Season), $"province {id}: season {c.Season}");
                Expect.True(StockHours.Contains(c.LegacyTimeOfDay), $"province {id}: hour {c.LegacyTimeOfDay}");
                n++;
            }
        }
        Expect.True(n > 22000, $"only {n} resolutions");
    }

    // A fight at a besieged tribal holding uses a village scene, and only one that the normal launch loads (most village scenes
    // live in SandBox, which PROTOCOL §3.1 does not launch; the module would swap them for its fallback plain).
    private static void VillageScenesLoadable()
    {
        var t = Tables;
        var resolver = new BattlefieldResolver(t);
        int villages = 0;
        foreach (var gfx in t.Terrain.Siege.Architecture.BuildingGfx.Keys)
        {
            foreach (int seq in Enumerable.Range(1, 12))
            {
                var c = resolver.Resolve(new BattlefieldInput
                {
                    ProvinceId = 8199, Year = 900, Month = 5, Day = seq, BattleSeq = seq, Holding = "tribal_holding", BuildingGfx = gfx, SiegeHere = true,
                });
                Expect.True(c.Relief, gfx);
                Expect.True(t.LoadableSceneIds.Contains(c.Scene), $"{gfx}: {c.Scene} is not in a launched module");
                Expect.True(c.Candidates.All(t.LoadableSceneIds.Contains), $"{gfx}: candidates {string.Join(",", c.Candidates)}");
                if (c.Kind == "village") villages++;
            }
        }
        Expect.Equal(t.Terrain.Siege.Architecture.BuildingGfx.Count * 12, villages, "every architecture has a loadable village scene");
    }

    // A data file caught half-written must not poison the table cache: the next battle loads again.
    private static void FailedLoadIsRetried()
    {
        string source = DataLocator.Resolve(null);
        string dir = Path.Combine(Path.GetTempPath(), "ck3xbl_mapping_selftest_" + Guid.NewGuid().ToString("N"));
        Directory.CreateDirectory(dir);
        try
        {
            foreach (var f in new[] { "terrain_scenes.json", "ck3_catalog.json", "bl_catalog.json", "bl_ruler_kits.json", "bl_scenes.json",
                         "ck3_province_terrain_index.json", "ck3_province_climate.json", "ck3_maa_index.json",
                         "ck3_combat_traits.json", "ck3_accolade_types.json", "ck3_artifact_to_bl_items.json" })
                File.Copy(Path.Combine(source, f), Path.Combine(dir, f));
            File.WriteAllText(Path.Combine(dir, "mapping.json"), "{ \"culture_profile_map\": ");   // caught mid-write
            Expect.Throws<JsonException>(() => MappingTables.Get(dir));
            Expect.Throws<JsonException>(() => MappingTables.Get(dir));
            File.Copy(Path.Combine(source, "mapping.json"), Path.Combine(dir, "mapping.json"), overwrite: true);
            var loaded = MappingTables.Get(dir);
            Expect.Equal(244, loaded.Mapping.CultureProfileMap.Count);
            Expect.True(ReferenceEquals(loaded, MappingTables.Get(dir)), "loaded once, then cached");
        }
        finally
        {
            try { Directory.Delete(dir, recursive: true); } catch (IOException) { }
        }
    }

