            ("huscarl", "norse", "culture_era_tribal", "forest", null, null, false, 4.83, 1, "huskarl_swordsman:0.48,sturgian_veteran_warrior:0.25,sturgian_shock_troop:0.17,sturgian_spearman:0.1"),
            ("crossbowmen", "east_asian", "culture_era_high_medieval", "plains", null, null, false, 3.75, 0.92, "imperial_crossbowman:1"),
            ("light_horsemen", "iberian_christian", "culture_era_high_medieval", "hills", null, null, false, 2.63, 1, "aserai_tribal_horseman:0.38,aserai_youth:0.37,aserai_mameluke_regular:0.25"),
            ("heavy_infantry_unknown_mod", "norse", "culture_era_early_medieval", null, null, "heavy_infantry", false, 4, 1, "sturgian_spearman:1"),
            ("onager", "western_feudal", "culture_era_high_medieval", null, null, null, true, 0, 0, ""),
            ("bowmen", "baltic_finnic", "culture_era_early_medieval", "taiga", null, null, false, 3.49, 1, "forest_people_tier_2:0.31,forest_people_tier_3:0.29,sturgian_hunter:0.2,sturgian_archer:0.2"),
            ("camel_rider", "arab", "culture_era_early_medieval", "desert", null, null, false, 4, 1, "jawwal_tier_3:0.5,ghilman_tier_3:0.5"),
            ("skirmishers_x", "berber", "culture_era_early_medieval", null, null, "skirmishers", false, 3, 1, "aserai_footman:1"),
            ("light_horsemen", "berber", "culture_era_early_medieval", "drylands", null, null, false, 3.75, 1, "beni_zilal_tier_3:0.38,aserai_faris:0.38,beni_zilal_tier_2:0.15,aserai_tribal_horseman:0.1"),
            ("armored_horsemen", "hungarian", "culture_era_high_medieval", "plains", null, null, false, 4.38, 1, "vlandian_cavalry:0.62,vlandian_vanguard:0.27,vlandian_champion:0.11"),
