    private static void GoldenAllocation()
    {
        // JS allocateAgents(..., 1000) gives 565/28/3 and 376/28/1 = 1001 agents; the bridge's cap guard trims one levy agent.
        var sides = new[] { new AllocationSide(), new AllocationSide() };
        sides[0].Groups.Add(new AllocationGroup { Id = "a:levy", IsLevy = true, Soldiers = 6000 });
        sides[0].Groups.Add(new AllocationGroup { Id = "a:fm", IsLevy = false, Soldiers = 300 });
        sides[0].Groups.Add(new AllocationGroup { Id = "a:el", IsLevy = false, Soldiers = 25, AgentMultiplier = 1.34 });
        sides[1].Groups.Add(new AllocationGroup { Id = "b:levy", IsLevy = true, Soldiers = 4000 });
        sides[1].Groups.Add(new AllocationGroup { Id = "b:hu", IsLevy = false, Soldiers = 300 });
        sides[1].Groups.Add(new AllocationGroup { Id = "b:x", IsLevy = false, Soldiers = 3 });
        AgentAllocator.Allocate(sides, 1000, 0, 40);
        Expect.Near(0.0940910801656003, sides[0].Scale, 1e-12);
        Expect.SequenceEqual(new[] { 28, 3 }, sides[0].Groups.Skip(1).Select(g => g.Agents));
        Expect.SequenceEqual(new[] { 28, 1 }, sides[1].Groups.Skip(1).Select(g => g.Agents));
        Expect.Equal(565 + 376 - 1, sides[0].Groups[0].Agents + sides[1].Groups[0].Agents);
        Expect.Equal(1000, sides[0].Agents + sides[1].Agents);
    }

    private static void GoldenCasualties()
    {
        var m = Tables.Mapping;
        List<CasualtyGroup> Mk(string side, double down, double fled) => new()
        {
            new CasualtyGroup { Id = side + ":levy", Soldiers = 6000, Agents = 767, Killed = JsCompat.RoundToInt(767 * down), Fled = JsCompat.RoundToInt(767 * fled), Toughness = 10 },
            new CasualtyGroup { Id = side + ":maa", Soldiers = 300, Agents = 38, Killed = JsCompat.RoundToInt(38 * down), Fled = JsCompat.RoundToInt(38 * fled), Toughness = 22, Pursuit = 10, Screen = 16 },
        };
        string Fmt(CasualtyOutcome o) => $"{o.PursuitFraction.ToString(System.Globalization.CultureInfo.InvariantCulture)}|" + string.Join(";", o.Winner.Concat(o.Loser).Select(g => $"{g.Id}:{g.Casualties}/{g.Fatal}/{g.Routed}"));
        var ck3 = new CasualtySettings();   // CK3 constants 0.3 / 0.05, as in the JS reference
        Expect.Equal("0.06|w:levy:1502/451/1051;w:maa:79/24/55;l:levy:2699/990/3086;l:maa:134/49/157",
            Fmt(CasualtyModel.Convert(m, Mk("w", 0.25, 0), Mk("l", 0.45, 0.2), ck3 with { Terrain = "forest", LoserIsDefender = true })));
        Expect.Equal("0.07|w:levy:1502/649/853;w:maa:79/34/45;l:levy:2699/1368/2730;l:maa:134/68/139",
            Fmt(CasualtyModel.Convert(m, Mk("w", 0.25, 0), Mk("l", 0.45, 0.2), ck3 with { Terrain = "wetlands", HarshWinter = true, LoserIsDefender = true })));
        Expect.Equal("1|w:levy:602/181/421;w:maa:32/10/22;l:levy:6000/6000/4200;l:maa:300/300/210",
            Fmt(CasualtyModel.Convert(m, Mk("w", 0.1, 0), Mk("l", 1, 0), ck3 with { Terrain = "plains", Annihilated = true, LoserIsDefender = false })));
    }

    // Rows with a holding under siege are relief battles: sieges stay in CK3 (PROTOCOL §0), so a castle or town gets the field
    // scene the reference resolves in its "field" mode for the same place and date (node battlefield_resolver.js, mode field), and
    // a tribal holding a village scene among those the normal launch loads (the reference does not filter by module: it picks
    // aserai_village_d from SandBox; the same hash over the loadable e/j/l list gives aserai_village_e).
    private static void GoldenBattlefield()
    {
        var resolver = new BattlefieldResolver(Tables);
        var cases = new (long Prov, string Date, int Seq, string? Winter, string? Holding, string? Gfx, string? Heritage, bool Siege, int Agents,
            string Kind, string Scene, string Season, double Hour, int Legacy, string Weather, string Preset, string TerrainType)[]
        {
            (5072, "1066.10.14", 17, null, null, null, null, false, 0, "field", "battle_terrain_026", "fall", 14.25, 15, "overcast", "TOD_12_00_Overcast", "Plain"),
            (8199, "870.7.1", 3, null, null, null, null, false, 0, "field", "battle_terrain_p", "summer", 10, 12, "heavy_rain", "TOD_12_00_HeavyRain", "Plain"),
            (2333, "1066.1.10", 5, "normal", null, null, null, false, 0, "field", "battle_terrain_biome_012", "winter", 13.25, 12, "blizzard", "TOD_12_00_Overcast", "Snow"),
            (4828, "1100.8.5", 9, null, null, null, null, false, 0, "field", "battle_terrain_biome_075", "summer", 18, 18, "dust", "TOD_06_30_Cloudy_sunset2", "Plain"),
            (5137, "1066.2.3", 11, "harsh", null, null, null, false, 900, "field", "battle_terrain_027", "winter", 9.5, 12, "snow", "TOD_08_00_Overcast", "Snow"),
            (9237, "1100.4.10", 2, null, null, null, null, false, 0, "field", "battle_terrain_018", "spring", 8.5, 6, "clear", "TOD_09_00_SemiCloudy", "Plain"),
            (2333, "1066.6.1", 4, null, "castle_holding", "western_building_gfx", "heritage_frankish", true, 0, "field", "battle_terrain_biome_012", "summer", 7.75, 6, "clear", "TOD_08_00_SemiCloudy", "Plain"),
            (496, "1100.5.5", 6, null, "city_holding", "byzantine_building_gfx", "heritage_byzantine", true, 0, "field", "battle_terrain_029", "spring", 12, 12, "clear", "TOD_12_00_SemiCloudy", "Plain"),
            (1527, "1066.12.5", 8, "mild", "castle_holding", "western_building_gfx", "heritage_goidelic", true, 0, "field", "battle_terrain_biome_131", "fall", 15.5, 15, "overcast", "TOD_12_00_Overcast", "Plain"),
            (8199, "870.3.3", 1, null, "tribal_holding", "african_building_gfx", null, true, 0, "village", "aserai_village_e", "summer", 15.25, 15, "overcast", "TOD_12_00_Overcast", "Plain"),
            (3000, "950.9.9", 21, null, null, null, null, false, 0, "field", "battle_terrain_biome_027", "summer", 11.25, 12, "clear", "TOD_11_00_SemiCloudy", "Plain"),
            (1500, "1200.11.20", 33, null, null, null, null, false, 0, "field", "battle_terrain_biome_027", "fall", 8.75, 6, "overcast", "TOD_08_00_Overcast", "Plain"),
        };
        foreach (var c in cases)
        {
            var d = c.Date.Split('.').Select(int.Parse).ToArray();
            var input = new BattlefieldInput
            {
                ProvinceId = c.Prov, Year = d[0], Month = d[1], Day = d[2], BattleSeq = c.Seq, Winter = c.Winter, Holding = c.Holding,
                BuildingGfx = c.Gfx, Heritage = c.Heritage, SiegeHere = c.Siege, Agents = c.Agents,
            };
            var b = resolver.Resolve(input);
            string id = $"{c.Prov}@{c.Date}";
            Expect.Equal(c.Kind, b.Kind, id + " kind");
            Expect.Equal(c.Scene, b.Scene, id + " scene");
            Expect.Equal(c.Siege, b.Relief, id + " relief");
            Expect.Equal(c.Season, b.Season, id + " season");
            Expect.Near(c.Hour, b.Hour, 1e-9, id + " hour");
            Expect.Equal(c.Legacy, b.LegacyTimeOfDay, id + " legacy hour");
            Expect.Equal(c.Weather, b.Weather, id + " weather");
            Expect.Equal(c.Preset, b.AtmospherePreset, id + " preset");
            Expect.Equal(c.TerrainType, b.TerrainTypeName, id + " terrain type");
            if (c.Siege && c.Kind == "field")
            {
                // A relief battle at a castle or town is the same field battle the place would have without the siege.
                var plain = resolver.Resolve(new BattlefieldInput
                {
                    ProvinceId = input.ProvinceId, Year = input.Year, Month = input.Month, Day = input.Day, BattleSeq = input.BattleSeq,
                    Winter = input.Winter, Holding = input.Holding, BuildingGfx = input.BuildingGfx, Heritage = input.Heritage, Agents = input.Agents,
                });
                Expect.SequenceEqual(plain.Candidates, b.Candidates, id + " candidates");
                Expect.False(plain.Relief);
            }
        }
    }

