    private static void LocationFactsParsing()
    {
        var t = Tables;
        LocationFacts Facts(Action<LocationInfo> fill)
        {
            var b = new BattleSnapshot();
            fill(b.Location);
            return LocationFacts.From(b, t);
        }
        // A logged "none" winter is a fact (no winter); an absent one leaves the season to the date and winter bias.
        Expect.Equal("none", Facts(l => l.Facts["winter"] = "none").Winter);
        Expect.Null(Facts(l => l.Facts["terrain"] = "hills").Winter);
        Expect.Equal("none", Facts(_ => { }).Winter, "no raw facts kept at all: trust the typed field");
        Expect.Null(Facts(l => l.Facts["winter"] = "none").WinterModifier);
        Expect.Equal("winter_harsh_modifier", Facts(l => l.Facts["winter"] = "harsh").WinterModifier);
        // Raw L facts fill typed fields the parser left at their defaults; the place culture supplies architecture.
        var f = Facts(l => { l.Facts["siege"] = "yes"; l.Facts["fort"] = "5"; l.Facts["coastal"] = "yes"; l.Facts["loc_culture"] = "norse"; });
        Expect.True(f.SiegeHere && f.Coastal && !f.Riverside);
        Expect.Equal("norse_building_gfx", f.BuildingGfx);
        Expect.Equal("heritage_north_germanic", f.Heritage);
        Expect.Equal("none", f.Holding);
    }

