    private static void GroupResultFallbacks()
    {
        var req = new SideRequest
        {
            Troops =
            {
                new TroopRequest { Id = "x", Count = 30, Group = "levy#1" },
                new TroopRequest { Id = "x", Count = 10, Group = "maa:bowmen#1#5" },
                new TroopRequest { Id = "y", Count = 20, Group = "maa:bowmen#1#5" },
            },
        };
        // Protocol v2: keyed by group.
        var byGroup = GroupResults.Resolve(req, new SideResult { Groups = { ["levy#1"] = new GroupResult { Spawned = 30, Killed = 12, Routed = 3 } } });
        Expect.Equal(new GroupStats(30, 30, 12, 0, 3), byGroup["levy#1"]);
        Expect.Equal(new GroupStats(30, 30, 0, 0, 0), byGroup["maa:bowmen#1#5"]);
        // Legacy module: keyed by troop id, split by requested share.
        var byTroop = GroupResults.Resolve(req, new SideResult
        {
            Groups = { ["x"] = new GroupResult { Spawned = 40, Killed = 20 }, ["y"] = new GroupResult { Spawned = 20, Killed = 4, Routed = 2 } },
        });
        Expect.Equal(new GroupStats(30, 30, 15, 0, 0), byTroop["levy#1"]);
        Expect.Equal(new GroupStats(30, 30, 9, 0, 2), byTroop["maa:bowmen#1#5"]);
        // Only side totals.
        var byTotals = GroupResults.Resolve(req, new SideResult { Spawned = 60, Killed = 30, Routed = 6 });
        Expect.Equal(new GroupStats(30, 30, 15, 0, 3), byTotals["levy#1"]);
    }

