    private static void FateOdds()
    {
        int[] Roll(Func<int, FateContext> ctx, int n = 4000)
        {
            var counts = new int[5];
            for (int tag = 1; tag <= n; tag++) counts[FateResolver.Downed(ctx(tag))]++;
            return counts;
        }
        FateContext Knight(int tag, bool player = false, bool real = false, bool loser = false, bool war = false, bool commander = false, int own = 1000, int enemy = 1000) => new()
        {
            Bid = 7, Character = new CharacterSnapshot { Tag = tag, Prowess = 10, Martial = 8 }, AsCommander = commander,
            IsCk3Player = player, PlayerDeathIsReal = real, OnLosingSide = loser, AtWar = war, OwnStrength = own, EnemyStrength = enemy,
        };
        // CK3 knight weights at prowess 10: wounded 75, maimed 26.7, killed 20 -> 61.6% / 21.9% / 16.4%.
        var k = Roll(t => Knight(t));
        Expect.Near(0.164, k[Fates.Killed] / 4000.0, 0.03);
        Expect.Near(0.219, k[Fates.Maimed] / 4000.0, 0.03);
        Expect.Equal(0, k[Fates.Captured] + k[Fates.Unharmed]);
        // The CK3 player never dies unless the hardcore option is on, and is never captured.
        Expect.Equal(0, Roll(t => Knight(t, player: true))[Fates.Killed]);
        Expect.True(Roll(t => Knight(t, player: true, real: true))[Fates.Killed] > 0);
        Expect.Equal(0, Roll(t => Knight(t, player: true, commander: true, loser: true, war: true))[Fates.Captured]);
        // A side five times stronger loses no one for good.
        var strong = Roll(t => Knight(t, own: 6000, enemy: 1000));
        Expect.Equal(0, strong[Fates.Killed] + strong[Fates.Maimed]);
        // Unwounded commanders are not killed outright (CK3 commander_killed is_valid); losing commanders at war get captured.
        var cmd = Roll(t => Knight(t, commander: true, loser: true, war: true));
        Expect.Equal(0, cmd[Fates.Killed]);
        Expect.Near(0.35, cmd[Fates.Captured] / 4000.0, 0.03);
        Expect.Equal(0, Roll(t => Knight(t, commander: true, loser: true, war: false))[Fates.Captured]);
        Expect.Equal(FateResolver.Downed(Knight(17)), FateResolver.Downed(Knight(17)));
    }

