    private static readonly BattleMapper Mapper = new();

    private static void CheckRequest(BattleSnapshot battle)
    {
        var options = new MapperOptions();
        var t = Tables;
        var plan = Mapper.Plan(battle, options);
        var req = plan.Request;

        Expect.Equal(battle.RequestId, req.Id);
        Expect.Equal(ProtocolInfo.Version, req.Protocol);
        Expect.Equal("field", req.Kind, "sieges stay in CK3 (PROTOCOL §0)");
        Expect.Null(req.Siege);
        Expect.True(t.LoadableSceneIds.Contains(req.Scene), $"scene {req.Scene} not in a launched module of bl_scenes.json");
        Expect.True(Seasons.Contains(req.Season), req.Season);
        Expect.True(StockHours.Contains((int)req.TimeOfDay), $"time {req.TimeOfDay}");
        Expect.True(req.PlayerSide is "attacker" or "defender");
        Expect.True(req.Presentation.Title.StartsWith("The Battle of ", StringComparison.Ordinal), req.Presentation.Title);
        foreach (var s in new[] { req.Presentation.Subtitle, req.Presentation.Detail, req.Presentation.Objective })
            Expect.True(!string.IsNullOrWhiteSpace(s));
        Expect.True(req.Presentation.Subtitle.Contains(" against ") && req.Presentation.Subtitle.Contains(" · "), req.Presentation.Subtitle);

        // Agents: budget, per-side floor, ratio.
        int total = req.Attacker.Troops.Sum(x => x.Count) + req.Defender.Troops.Sum(x => x.Count);
        Expect.True(total <= options.MaxAgentsTotal, $"{total} agents > {options.MaxAgentsTotal}");
        foreach (var side in new[] { plan.Attacker, plan.Defender })
        {
            Expect.True(side.GroupAgents >= Math.Min(options.MinAgentsPerSide, side.Soldiers), $"{side.Key}: {side.GroupAgents} agents for {side.Soldiers} men");
            var sr = side.Key == SideKey.Attacker ? req.Attacker : req.Defender;
            Expect.Equal(side.TroopAgents, sr.Troops.Sum(x => x.Count));
            Expect.True(!string.IsNullOrEmpty(sr.Name) && t.Mapping.Profiles.Values.Any(p => p.BlCulture == sr.Culture), $"{sr.Name}/{sr.Culture}");
        }
        if (!plan.Attacker.Floored && !plan.Defender.Floored)
        {
            double want = plan.Attacker.Soldiers / (double)plan.Defender.Soldiers;
            double have = plan.Attacker.GroupAgents / (double)plan.Defender.GroupAgents;
            Expect.True(Math.Abs(have / want - 1) <= 0.10, $"agent ratio {have:F3} vs soldier ratio {want:F3}");
        }

        // Troops and groups.
        foreach (var sr in new[] { req.Attacker, req.Defender })
        {
            foreach (var tr in sr.Troops)
            {
                Expect.True(t.IsSpawnableTroop(tr.Id), $"troop {tr.Id} missing from bl_catalog or not CustomGame-loaded");
                Expect.True(tr.Count > 0 && GroupKey.TryParse(tr.Group, out _), $"{tr.Id} x{tr.Count} group {tr.Group}");
            }
        }
        foreach (var side in battle.Sides)
        {
            var sr = side.Key == SideKey.Attacker ? req.Attacker : req.Defender;
            var groups = sr.Troops.Select(x => x.Group).Distinct().Select(g => { GroupKey.TryParse(g, out var k); return k; }).ToList();
            foreach (var army in side.Armies)
            {
                Expect.Equal(army.Levies > 0, groups.Contains(GroupKey.Levy(army.Tag)), $"levy group of army {army.Tag}");
                foreach (var reg in army.Regiments.Where(x => x.Current > 0))
                {
                    bool excluded = t.Mapping.MaaTier.TryGetValue(reg.MaaKey, out var info) && info.Excluded;
                    Expect.Equal(!excluded, groups.Contains(GroupKey.Maa(reg.MaaKey, army.Tag, reg.RegimentId)), $"group of {reg.MaaKey}#{army.Tag}");
                }
            }
        }

        // Heroes.
        var heroes = req.Attacker.Heroes.Concat(req.Defender.Heroes).ToList();
        Expect.Equal(heroes.Count, heroes.Select(h => h.Key).Distinct().Count());
        Expect.Equal(heroes.Count, heroes.Select(h => h.Name).Distinct(StringComparer.OrdinalIgnoreCase).Count());
        Expect.True(heroes.Count(h => h.IsPlayer) <= 1);
        foreach (var h in heroes)
        {
            Expect.True(h.Name.Length > 0 && h.Name.IndexOfAny(new[] { '{', '}', '.' }) < 0, $"bad name '{h.Name}'");
            Expect.True(h.Role is "player" or "commander" or "knight", h.Role);
            Expect.True(h.Formation is "Infantry" or "Ranged" or "Cavalry" or "HorseArcher", h.Formation);
            Expect.True(h.Equipment?.Roster is { } roster && t.Kits.ContainsKey(roster), $"{h.Name}: roster {h.Equipment?.Roster}");
            Expect.True(h.Level is >= 1 and <= 62 && h.Age is >= 16 and <= 99 && h.HealthMultiplier is >= 1 and <= 3);
            Expect.True(h.Skills.ContainsKey("Tactics") && h.Skills.ContainsKey("OneHanded"));
        }
        foreach (var sr in new[] { req.Attacker, req.Defender })
        {
            bool heroGeneral = sr.Heroes.Any(h => h.Key == sr.General);
            bool stockGeneral = t.Mapping.Commanders.Values.SelectMany(c => c.MaleMounted.Concat(c.MaleFoot).Concat(c.Female)).Any(c => c.Character == sr.General);
            Expect.True(heroGeneral || stockGeneral, $"general {sr.General}");
            if (heroGeneral && sr.Heroes.Count > 1)
                Expect.True(sr.Heroes.Single(h => h.Key == sr.General).Level >= sr.Heroes.Max(h => h.Level), "the general has the highest level on his side");
        }

        // Deterministic: the same snapshot gives the same request, byte for byte.
        Expect.Equal(JsonSerializer.Serialize(req, Json), JsonSerializer.Serialize(Mapper.BuildRequest(battle, options), Json));
    }

    private static void CheckOutcome(BattleSnapshot battle)
    {
        var options = new MapperOptions();
        var t = Tables;
        var req = Mapper.BuildRequest(battle, options);
        foreach (var winner in new[] { "attacker", "defender" })
        {
            var result = Synthetic(req, winner);
            var o = Mapper.BuildOutcome(battle, req, result, options);
            Expect.Equal(winner == "attacker" ? 1 : 2, o.OutcomeCode);
            Expect.Equal(battle.Bid, o.Bid);
            Expect.Equal(battle.Location.ProvinceId, o.ProvinceId);
            // Every army loses men in this result, so every army is listed, and each entry changes something.
            Expect.Equal(battle.Sides.Sum(s => s.Armies.Count(a => a.Tag > 0)), o.Armies.Count);
            Expect.True(o.Armies.All(a => a.LevyLossPermille > 0 || a.Maa.Count > 0));
            var playerSideKey = req.PlayerSide == "attacker" ? SideKey.Attacker : SideKey.Defender;
            Expect.Equal(o.PlayerWon, req.PlayerSide == winner);

            int totalDead = 0;
            foreach (var a in o.Armies)
            {
                Expect.True(a.LevyLossPermille is >= 0 and <= 1000);
                Expect.True(a.Maa.Count <= OutcomeBuilder.MaaSlotsPerArmy);
                Expect.Equal(a.Maa.Count, a.Maa.Select(x => x.MaaKey).Distinct().Count());
                foreach (var m in a.Maa)
                {
                    Expect.True(m.SurvivorSharePermille is >= 0 and <= 1000);
                    Expect.Equal(t.MaaIndex[m.MaaKey], m.MaaIndex);
                }
                totalDead += SimulateCk3Apply(battle, a);
            }
            // Re-applying the outcome the way CK3 does (deplete, then set MaA) reproduces the computed fatal losses.
            int computed = o.MyLost + o.EnemyLost;
            int tol = o.Armies.Sum(a => ToleranceOf(battle, a));
            Expect.True(Math.Abs(totalDead - computed) <= tol, $"CK3 apply loses {totalDead} men, mapper computed {computed} (± {tol})");
            Expect.True(o.MyLost <= battle.Side(playerSideKey).Armies.Sum(a => a.Size));
            Expect.True(o.EnemyLost > 0 && o.MyLost > 0);

            // Exactly the downed heroes are listed (an unharmed entry would only cost keypad chords); killers are enemies.
            var attackerTags = req.Attacker.Heroes.Select(h => h.Tag).ToHashSet();
            var downedTags = result.Heroes.Where(h => h.State is "killed" or "wounded").Select(h => h.Tag).ToHashSet();
            Expect.True(downedTags.SetEquals(o.Characters.Select(c => c.Tag)), "listed characters = downed heroes");
            Expect.Equal(o.Characters.Count, o.Characters.Select(c => c.Tag).Distinct().Count());
            foreach (var c in o.Characters)
            {
                Expect.True(c.Fate is >= Fates.Wounded and <= Fates.Killed, $"fate {c.Fate}");
                Expect.True(c.KillerTag == 0 || attackerTags.Contains(c.KillerTag) != attackerTags.Contains(c.Tag), $"killer {c.KillerTag} of {c.Tag}");
            }
            var avatar = req.Attacker.Heroes.Concat(req.Defender.Heroes).FirstOrDefault(h => h.IsPlayer);
            if (avatar is not null)
            {
                if (avatar.Role == "player")
                {
                    Expect.Equal(avatar.Tag, o.Characters[0].Tag, "the player's fate comes first");
                    Expect.True(o.Characters[0].Fate is Fates.Wounded or Fates.Maimed, $"player killed in Bannerlord -> fate {o.Characters[0].Fate}");
                }
                Expect.Equal(5, o.MyKills);
            }
            Expect.True(o.Summary.Length > 0 && (o.PlayerWon ? o.Summary.StartsWith("Victory") : o.Summary.StartsWith("Defeat")), o.Summary);

            var again = Mapper.BuildOutcome(battle, req, result, options);
            Expect.Equal(JsonSerializer.Serialize(o, Json), JsonSerializer.Serialize(again, Json));
        }
    }

    // CK3 applies deplete_army_by_percentage (levies and every regiment by the same fraction), then sets each listed MaA
    // type to max x share. Returns the men the army loses that way.
    private static int SimulateCk3Apply(BattleSnapshot battle, ArmyLoss a)
    {
        var army = battle.Sides.SelectMany(s => s.Armies).Single(x => x.Tag == a.ArmyTag);
        double f = a.LevyLossPermille / 1000.0;
        double after = army.Levies * (1 - f);
        foreach (var reg in army.Regiments)
        {
            var slot = a.Maa.FirstOrDefault(m => m.MaaKey == reg.MaaKey);
            after += slot is not null ? reg.Max * slot.SurvivorSharePermille / 1000.0 : reg.Current * (1 - f);
        }
        return (int)Math.Round(army.Levies + army.Regiments.Sum(r => r.Current) - after);
    }

    // Permille rounding: half a permille of every pool, plus one man per pool.
    private static int ToleranceOf(BattleSnapshot battle, ArmyLoss a)
    {
        var army = battle.Sides.SelectMany(s => s.Armies).Single(x => x.Tag == a.ArmyTag);
        return (int)Math.Ceiling((army.Levies + army.Regiments.Sum(r => Math.Max(r.Current, r.Max))) / 2000.0) + army.Regiments.Count + 1;
    }

    /// <summary>A plausible Bannerlord result: the loser loses 45% killed and 20% routed, the winner 20% killed; the avatar falls
    /// after 5 kills, struck by the enemy general; the loser's general falls to the avatar.</summary>
    private static BattleResult Synthetic(BattleRequest req, string winner, string status = "result")
    {
        SideResult Side(SideRequest s, bool won)
        {
            var r = new SideResult();
            foreach (var g in s.Troops.GroupBy(x => x.Group))
            {
                int n = g.Sum(x => x.Count);
                var gr = new GroupResult { Requested = n, Spawned = n, Killed = (int)(n * (won ? 0.2 : 0.45)), Routed = won ? 0 : (int)(n * 0.2) };
                r.Groups[g.Key!] = gr;
                r.Requested += n; r.Spawned += n; r.Killed += gr.Killed; r.Routed += gr.Routed;
            }
            return r;
        }
        var result = new BattleResult
        {
            Id = req.Id, Status = status, Winner = winner, DurationSeconds = 300,
            Attacker = Side(req.Attacker, winner == "attacker"), Defender = Side(req.Defender, winner == "defender"),
        };
        var playerSide = req.PlayerSide == "attacker" ? req.Attacker : req.Defender;
        var enemySide = req.PlayerSide == "attacker" ? req.Defender : req.Attacker;
        string? enemyGeneral = enemySide.Heroes.Any(h => h.Key == enemySide.General) ? enemySide.General : null;
        foreach (var h in req.Attacker.Heroes.Concat(req.Defender.Heroes))
        {
            bool onLoser = (winner == "attacker" ? req.Defender : req.Attacker).Heroes.Contains(h);
            var hr = new HeroResult { Key = h.Key, Ck3Id = h.Ck3Id, Tag = h.Tag, State = "alive" };
            if (h.IsPlayer) { hr.State = "killed"; hr.Kills = 5; hr.KilledBy = enemyGeneral; }
            else if (h.Key == enemySide.General && onLoser) { hr.State = "killed"; hr.KilledBy = playerSide.Heroes.FirstOrDefault(x => x.IsPlayer)?.Key; }
            else if (onLoser && h.Tag % 2 == 0) hr.State = "killed";
            else if (onLoser) hr.State = "routed";
            result.Heroes.Add(hr);
        }
        return result;
    }

