    private static void VassalBattle()
    {
        // Only the player's realm fights: the vassal Mallaya commands, the player is logged as C|PLAYER (PROTOCOL §5.2), s_player_in = 0.
        var battle = Scenarios.IndianProbe3();
        battle.Defender.PlayerIn = false;
        var me = battle.Defender.Characters.Single(c => c.IsPlayer);
        me.IsCommander = false; me.IsPrimary = false; me.Role = "PLAYER";
        var mallaya = battle.Defender.Characters.Single(c => c.Ref.Name == "Mallaya");
        mallaya.IsKnight = false; mallaya.IsCommander = true; mallaya.IsPrimary = true; mallaya.Role = "CMD";
        battle.Defender.Armies[0].Commander = mallaya.Ref;
        battle.Defender.Primary = mallaya.Ref;
        var req = Mapper.BuildRequest(battle, new MapperOptions());
        Expect.Equal("defender", req.PlayerSide);
        Expect.True(req.PlayerIsGeneral);
        Expect.Equal(mallaya.Ref.Ck3Id, req.Defender.Heroes.Single(h => h.IsPlayer).Ck3Id);
        Expect.False(req.Defender.Heroes.Any(h => h.Ck3Id == 10811), "C|PLAYER alone does not put the player on the field");

        // Nothing identifies the player at all: the defenders are assumed to be the player's realm.
        battle.PlayerCk3Id = 1;
        foreach (var c in battle.Defender.Characters) c.IsPlayer = false;
        var anon = Mapper.BuildRequest(battle, new MapperOptions());
        Expect.Equal("defender", anon.PlayerSide);
        Expect.Equal(mallaya.Ref.Ck3Id, anon.Defender.Heroes.Single(h => h.IsPlayer).Ck3Id);
    }

    private static void AbortCancelAndProtection()
    {
        var battle = Scenarios.IndianProbe3();
        var options = new MapperOptions();
        var req = Mapper.BuildRequest(battle, options);

        var cancelled = Mapper.BuildOutcome(battle, req, new BattleResult { Id = req.Id, Status = "cancelled", Winner = "none" }, options);
        Expect.Equal(4, cancelled.OutcomeCode);
        Expect.Equal(0, cancelled.Armies.Count + cancelled.Characters.Count + cancelled.MyLost + cancelled.EnemyLost);

        var aborted = Mapper.BuildOutcome(battle, req, Synthetic(req, "attacker", "aborted"), options);
        Expect.Equal(3, aborted.OutcomeCode);
        Expect.False(aborted.PlayerWon);
        Expect.True(aborted.MyLost > 0 && aborted.Summary.StartsWith("The battle at Orangallu was broken off", StringComparison.Ordinal), aborted.Summary);
        Expect.Equal(0, aborted.PrestigeBonus);

        // Hardcore: the avatar's Bannerlord death may become a CK3 death. The raid avatar rides as a knight, so across many
        // battles it sometimes does; without the option it never does. The Orangallu avatar commands, and unwounded commanders
        // are never killed outright in CK3, hardcore or not.
        var raid = Scenarios.TinyRaid();
        var raidReq = Mapper.BuildRequest(raid, options);
        int raidDeaths = 0, commanderDeaths = 0;
        for (int bid = 1; bid <= 300; bid++)
        {
            raid.Bid = bid;
            battle.Bid = bid;
            var hard = new MapperOptions { PlayerDeathIsReal = true };
            if (Mapper.BuildOutcome(raid, raidReq, Synthetic(raidReq, "attacker"), hard).Characters.Single(c => c.Tag == 53).Fate == Fates.Killed) raidDeaths++;
            if (Mapper.BuildOutcome(battle, req, Synthetic(req, "attacker"), hard).Characters.Single(c => c.Tag == 3).Fate == Fates.Killed) commanderDeaths++;
            Expect.True(Mapper.BuildOutcome(raid, raidReq, Synthetic(raidReq, "attacker"), options).Characters.Single(c => c.Tag == 53).Fate is Fates.Wounded or Fates.Maimed);
        }
        Expect.True(raidDeaths is > 20 and < 100, $"{raidDeaths}/300 hardcore knight-avatar deaths");
        Expect.Equal(0, commanderDeaths);
        var won = Mapper.BuildOutcome(Scenarios.IndianProbe3(), req, Synthetic(req, "defender"), options);
        Expect.True(won.PlayerWon && won.PrestigeBonus == 2 * 5 + 25 && won.Summary.Contains("You struck down 5 foes"), won.Summary);
    }

