    // The module's IAgentStateDecider splits downed agents into killed and wounded at random. CK3's losses must not depend on that
    // split (no switch of model when a wounded agent appears), and the configured conversion shares must apply.
    private static void CasualtiesIgnoreSplit()
    {
        var battle = Scenarios.IndianProbe3();
        var options = new MapperOptions();
        var req = Mapper.BuildRequest(battle, options);
        BattleResult Split(double killedShare)
        {
            var r = Synthetic(req, "defender");
            foreach (var g in r.Attacker.Groups.Values.Concat(r.Defender.Groups.Values))
            {
                int downed = g.Killed + g.Wounded;
                g.Killed = JsCompat.RoundToInt(downed * killedShare);
                g.Wounded = downed - g.Killed;
            }
            return r;
        }
        var allKilled = Mapper.BuildOutcome(battle, req, Split(1), options);
        foreach (double share in new[] { 0.3, 0.97, 0 })
        {
            var o = Mapper.BuildOutcome(battle, req, Split(share), options);
            Expect.Equal(allKilled.MyLost, o.MyLost, $"my losses at killed share {share}");
            Expect.Equal(allKilled.EnemyLost, o.EnemyLost, $"enemy losses at killed share {share}");
            Expect.Equal(JsonSerializer.Serialize(allKilled.Armies, Json), JsonSerializer.Serialize(o.Armies, Json));
        }
        // The player defends and wins: the loser share drives the enemy's losses, the winner share his own.
        var defaults = Mapper.BuildOutcome(battle, req, Split(0.3), options);
        Expect.True(Mapper.BuildOutcome(battle, req, Split(0.3), new MapperOptions { KilledToCk3DeadShareLoser = 0.9 }).EnemyLost > defaults.EnemyLost);
        Expect.True(Mapper.BuildOutcome(battle, req, Split(0.3), new MapperOptions { KilledToCk3DeadShareWinner = 0.2 }).MyLost < defaults.MyLost);
    }

    // Bannerlord "wounded" (knocked out) and "killed" both mean the hero fell; CK3's odds decide, so both give the same fates.
    private static void WoundedHeroesRollLikeKilled()
    {
        var options = new MapperOptions();
        int deaths = 0;
        for (int bid = 1; bid <= 200; bid++)
        {
            var battle = Scenarios.FrankishWinterHills();
            battle.Bid = bid;
            var req = Mapper.BuildRequest(battle, options);
            var killed = Synthetic(req, "attacker");
            var knockedOut = Synthetic(req, "attacker");
            foreach (var h in knockedOut.Heroes.Where(h => h.State == "killed")) h.State = "wounded";
            var a = Mapper.BuildOutcome(battle, req, killed, options);
            var b = Mapper.BuildOutcome(battle, req, knockedOut, options);
            Expect.Equal(JsonSerializer.Serialize(a.Characters, Json), JsonSerializer.Serialize(b.Characters, Json), $"bid {bid}");
            deaths += b.Characters.Count(c => c.Fate == Fates.Killed);
        }
        Expect.True(deaths > 20, $"only {deaths} knights knocked out in Bannerlord died in CK3 over 200 battles");
    }

    // The stand-in commander the user plays when the ruler stays home is an ordinary CK3 character: he can be captured. The CK3
    // player in person never is (and never dies without PlayerDeathIsReal).
    private static void StandInAvatarOdds()
    {
        var options = new MapperOptions();
        int standInCaptures = 0, playerCaptures = 0;
        for (int bid = 1; bid <= 200; bid++)
        {
            var home = Scenarios.PlayerStaysHome();
            home.Bid = bid;
            var req = Mapper.BuildRequest(home, options);
            var standIn = req.Defender.Heroes.Single(h => h.IsPlayer);
            Expect.Equal("commander", standIn.Role);
            if (Mapper.BuildOutcome(home, req, Synthetic(req, "attacker"), options).Characters.Single(c => c.Tag == standIn.Tag).Fate == Fates.Captured)
                standInCaptures++;

            var present = Scenarios.IndianProbe3();
            present.Bid = bid;
            var presentReq = Mapper.BuildRequest(present, options);
            if (Mapper.BuildOutcome(present, presentReq, Synthetic(presentReq, "attacker"), options).Characters.Single(c => c.Tag == 3).Fate == Fates.Captured)
                playerCaptures++;
        }
        Expect.Equal(0, playerCaptures);
        Expect.True(standInCaptures is > 40 and < 110, $"{standInCaptures}/200 captures of the losing stand-in commander (p = 0.35)");
    }

    // The module credits any hero who downs an agent, allies included. CK3 must never get an ally as the killer, and the player's
    // kills must not count a knight of his own host.
    private static void FriendlyFire()
    {
        var battle = Scenarios.FrankishWinterHills();
        var options = new MapperOptions();
        var req = Mapper.BuildRequest(battle, options);
        var result = Synthetic(req, "attacker");
        var me = req.Attacker.Heroes.Single(h => h.IsPlayer);
        Expect.Equal(me.Key, req.Attacker.General);
        var ally = req.Attacker.Heroes.First(h => !h.IsPlayer && h.Role == "knight");
        var allyResult = result.Heroes.Single(h => h.Key == ally.Key);
        allyResult.State = "wounded";
        allyResult.KilledBy = me.Key;
        result.Heroes.Single(h => h.Key == me.Key).Kills += 1;
        var ulrich = req.Defender.Heroes.Single(h => h.Name == "Ulrich");
        var bernard = req.Defender.Heroes.Single(h => h.Name == "Bernard of Bavaria");
        var ulrichResult = result.Heroes.Single(h => h.Key == ulrich.Key);
        ulrichResult.State = "killed";
        ulrichResult.KilledBy = bernard.Key;

        var o = Mapper.BuildOutcome(battle, req, result, options);
        int konradTag = req.Defender.Heroes.Single(h => h.Key == req.Defender.General).Tag;
        Expect.Equal(konradTag, o.Characters.Single(c => c.Tag == ally.Tag).KillerTag, "the enemy general, not the player");
        Expect.Equal(me.Tag, o.Characters.Single(c => c.Tag == ulrich.Tag).KillerTag, "the enemy general, not a fellow German");
        Expect.Equal(5, o.MyKills);
    }

    // Only entries that change CK3 are sent: every army slot and character slot costs keypad chords.
    private static void OnlyChangesListed()
    {
        var battle = Scenarios.FrankishWinterHills();
        var options = new MapperOptions();
        var req = Mapper.BuildRequest(battle, options);
        var result = Synthetic(req, "attacker");
        // Losses only among the Aquitaine knights (no levy loss there) and the Swabian levies; the Rouergue host is untouched.
        foreach (var (key, g) in result.Attacker.Groups.Concat(result.Defender.Groups))
        {
            bool hit = key == "levy#21" || key.StartsWith("maa:armored_horsemen#11#", StringComparison.Ordinal);
            g.Killed = hit ? Math.Max(1, g.Requested / 4) : 0;
            g.Wounded = 0;
            g.Routed = 0;
        }
        foreach (var h in result.Heroes) { h.State = "alive"; h.KilledBy = null; h.Kills = 0; }
        string konrad = req.Defender.General;
        result.Heroes.Single(h => h.Key == konrad).State = "wounded";

        var o = Mapper.BuildOutcome(battle, req, result, options);
        Expect.SequenceEqual(new[] { 11, 21 }, o.Armies.Select(a => a.ArmyTag).OrderBy(t => t));
        var aquitaine = o.Armies.Single(a => a.ArmyTag == 11);
        Expect.Equal(0, aquitaine.LevyLossPermille);
        Expect.SequenceEqual(new[] { "armored_horsemen" }, aquitaine.Maa.Select(m => m.MaaKey), "no pair for types that lost nobody");
        Expect.True(aquitaine.Maa[0].SurvivorSharePermille < 1000);
        var swabia = o.Armies.Single(a => a.ArmyTag == 21);
        Expect.True(swabia.LevyLossPermille > 0);
        Expect.True(swabia.Maa.Count == 3 && swabia.Maa.All(m => m.SurvivorSharePermille == 1000), "the deplete's cut of the MaA is restored");
        int simulated = o.Armies.Sum(a => SimulateCk3Apply(battle, a));
        Expect.True(Math.Abs(simulated - (o.MyLost + o.EnemyLost)) <= o.Armies.Sum(a => ToleranceOf(battle, a)), $"{simulated} vs {o.MyLost + o.EnemyLost}");
        int konradTag = req.Defender.Heroes.Single(h => h.Key == konrad).Tag;
        Expect.SequenceEqual(new[] { konradTag }, o.Characters.Select(c => c.Tag), "unharmed heroes are not listed");
    }

