    /// <summary>A restricted troop where no allow entry admits it (wolf-skin bandits among the Vlandian levies) makes the data
    /// unusable: MappingTables.Load refuses it, so no troop choice can return one.</summary>
    private static void LoadRefusesRestrictedTroop()
    {
        string source = DataLocator.Resolve(null);
        string dir = Path.Combine(Path.GetTempPath(), "ck3xbl_mapping_selftest_" + Guid.NewGuid().ToString("N"));
        Directory.CreateDirectory(dir);
        try
        {
            foreach (var f in Directory.GetFiles(source, "*.json")) File.Copy(f, Path.Combine(dir, Path.GetFileName(f)));
            var mapping = JsonNode.Parse(File.ReadAllText(Path.Combine(source, "mapping.json")))!;
            mapping["levy_by_era"]!["culture_era_early_medieval"]!["vlandia"]!.AsArray().Add(new JsonObject { ["troop"] = "wolfskins_tier_1", ["weight"] = 0.05 });
            File.WriteAllText(Path.Combine(dir, "mapping.json"), mapping.ToJsonString());
            var e = Expect.Throws<InvalidDataException>(() => MappingTables.Load(dir));
            Expect.True(e.Message.Contains("levy_by_era.culture_era_early_medieval.vlandia: restricted troop 'wolfskins_tier_1'", StringComparison.Ordinal), e.Message);
        }
        finally
        {
            try { Directory.Delete(dir, recursive: true); } catch (IOException) { }
        }
    }

