    /// <summary>
    /// The Hastings test (from a live battle): South Seaxe is forest, William besieges its castle, and Harold's relief battle
    /// opened in a dense spruce wood under the words "Fields before South Seaxe". A castle or town relief battle in wooded terrain is
    /// fought on the open farmland around the holding (rule 4), and its detail names the ground actually used (rule 5).
    /// </summary>
    private static void ReliefInWoods()
    {
        var t = Tables;
        var tags = SceneVegetation.ReadTags(Path.Combine(t.Directory, "terrain_scenes.json"));
        var farmland = t.Terrain.Terrain["farmlands"].Scenes!.Buckets["any"];
        var resolver = new BattlefieldResolver(t);
        BattlefieldInput Seaxe(bool siege) => new()
        {
            ProvinceId = 1506, Year = 1067, Month = 10, Day = 14, BattleSeq = 1, Holding = "castle_holding", BuildingGfx = "western_building_gfx",
            Heritage = "heritage_west_germanic", SiegeHere = siege,
        };
        var b = resolver.Resolve(Seaxe(true));
        Expect.Equal(("forest", "temperate", "farmlands"), (b.Terrain, b.Climate, b.PoolTerrain));
        Expect.Equal("terrain", b.ListSource, "no chance-based coast lead away from the holding");
        Expect.True(farmland.Contains(b.Scene) && tags[b.Scene] is SceneVegetation.Open or SceneVegetation.DeciduousOpen, b.Scene);
        var unbesieged = resolver.Resolve(Seaxe(false));
        Expect.Equal(("forest", "coastal_far"), (unbesieged.PoolTerrain, unbesieged.ListSource), "without the siege: the forest coast as before");
        Expect.False(t.Terrain.Terrain["forest"].Scenes!.Buckets["any"].Any(id => tags[id] == SceneVegetation.ConiferDense),
            "the temperate forest pool holds no dense conifer wood (rule 2)");

        var req = Mapper.BuildRequest(Scenarios.SouthSeaxe(), new MapperOptions());
        Expect.True(farmland.Contains(req.Scene), req.Scene);
        Expect.Equal("Fields before South Seaxe", req.Presentation.Detail);
        Expect.Equal("Break the siege of South Seaxe", req.Presentation.Objective);

        // A relief battle on ground that is not open names it.
        var hills = Scenarios.SiegeCastle();
        hills.Location.Terrain = hills.Location.Facts["terrain"] = "hills";
        Expect.Equal("Hills before Angers", Mapper.BuildRequest(hills, new MapperOptions()).Presentation.Detail);
    }

    // ---- battle clock (PROTOCOL §14) ----------------------------------------------------------------------------------

    private static int SideDead(Ck3Outcome o, SideKey side) => o.GroupLosses.Where(g => g.Side == side).Sum(g => g.Dead);

    /// <summary>Each listed army's levy survivors in a first clash: its levies less the levy dead and the dead of the indexed MaA
    /// types without a pair (folded into the levies; unindexed types keep CK3's own losses).</summary>
    private static void ExpectLevySurvivors(BattleSnapshot planned, Ck3Outcome o)
    {
        foreach (var a in o.Armies)
        {
            var army = planned.Sides.SelectMany(s => s.Armies).Single(x => x.Tag == a.ArmyTag);
            int levyDead = 0, foldedDead = 0;
            foreach (var g in o.GroupLosses)
            {
                if (!GroupKey.TryParse(g.GroupKey, out var key) || key.ArmyTag != a.ArmyTag) continue;
                if (key.Kind == GroupKind.Levy) levyDead += g.Dead;
                else if (a.Maa.All(m => m.MaaKey != key.MaaKey) && Tables.MaaIndex.ContainsKey(key.MaaKey!)) foldedDead += g.Dead;
            }
            Expect.Equal(Math.Max(0, army.Levies - levyDead - foldedDead), a.LevySurvivors, $"army {a.ArmyTag} levy survivors");
        }
    }

    private static void OutcomePayloadV4()
    {
        var battle = Scenarios.Huge();
        var options = new MapperOptions();
        var req = Mapper.BuildRequest(battle, options);
        var result = Synthetic(req, "attacker");
        var o = Mapper.BuildOutcome(battle, req, result, options);
        Expect.Equal((4, 12, 0, 1), (o.PayloadVersion, o.PaceDays, o.ParentBid, o.Clash));

        // The per-group dead name the request's troop groups verbatim (knight retinues are no CK3 soldiers) and add up to the targets.
        var groups = req.Attacker.Troops.Concat(req.Defender.Troops).Select(x => x.Group).ToHashSet();
        Expect.True(o.GroupLosses.All(g => groups.Contains(g.GroupKey) && GroupKey.TryParse(g.GroupKey, out var k) && k.Kind != GroupKind.Retinue));
        Expect.Equal(o.GroupLosses.Count, o.GroupLosses.Select(g => g.GroupKey).Distinct().Count());
        Expect.Equal(SideDead(o, SideKey.Defender), o.AttackerKillTarget, "the attacker side must count the defender's dead");
        Expect.Equal(SideDead(o, SideKey.Attacker), o.DefenderKillTarget);
        Expect.Equal((o.DefenderKillTarget, o.AttackerKillTarget), (o.MyLost, o.EnemyLost), "the player attacks");

        // End states: absolute levy survivors; the Imperial Host has more MaA types than pairs, and their dead come out of its levies.
        ExpectLevySurvivors(battle, o);
        var imperial = o.Armies.Single(a => a.ArmyTag == 51);
        int folded = o.GroupLosses.Where(g => GroupKey.TryParse(g.GroupKey, out var k) && k.ArmyTag == 51 && k.Kind == GroupKind.Maa
                                              && imperial.Maa.All(m => m.MaaKey != k.MaaKey)).Sum(g => g.Dead);
        Expect.True(imperial.Maa.Count == OutcomeBuilder.MaaSlotsPerArmy && folded > 0, $"{imperial.Maa.Count} pairs, {folded} folded dead");

        foreach (var (pace, sent) in new[] { (3, 6), (13, 13), (20, 13) })
        {
            var paced = new MapperOptions();
            paced.BattleClock.PaceDays = pace;
            Expect.Equal(sent, Mapper.BuildOutcome(battle, req, result, paced).PaceDays, $"pace day {pace}");
        }
        // A loss too small for a permille still changes the absolute levy survivors: listed in payload 4, left out of payload 3.
        var big = Scenarios.SiegeCastle();
        var anjou = big.Attacker.Armies.Single();
        anjou.Levies = 300_000;
        big.Attacker.Size = anjou.Size = anjou.Levies + anjou.Regiments.Sum(r => r.Current);
        var wide = new MapperOptions { MaxAgentsTotal = 3000 };
        var bigReq = Mapper.BuildRequest(big, wide);
        var oneDown = Synthetic(bigReq, "attacker");
        foreach (var (key, g) in oneDown.Attacker.Groups.Concat(oneDown.Defender.Groups)) (g.Killed, g.Wounded, g.Routed) = (key == "levy#41" ? 1 : 0, 0, 0);
        foreach (var h in oneDown.Heroes) { h.State = "alive"; h.KilledBy = null; h.Kills = 0; }
        var slight = Mapper.BuildOutcome(big, bigReq, oneDown, wide).Armies.Single();
        Expect.Equal((41, 0, 0), (slight.ArmyTag, slight.LevyLossPermille, slight.Maa.Count));
        Expect.True(slight.LevySurvivors is > 0 and < 300_000, $"{slight.LevySurvivors} levies left");
        wide.BattleClock.Enabled = false;
        Expect.Equal(0, Mapper.BuildOutcome(big, bigReq, oneDown, wide).Armies.Count, "payload 3: nothing to change");

        // A cancelled clash is payload 4 too (a cancelled reinforcement clash hands its parent back), with nothing to apply.
        var cancel = Mapper.BuildOutcome(battle, req, Synthetic(req, "attacker", "cancelled"), options);
        Expect.Equal((4, 4, 0, 0, 0), (cancel.OutcomeCode, cancel.PayloadVersion, cancel.Armies.Count, cancel.GroupLosses.Count, cancel.AttackerKillTarget));
    }

    /// <summary>With the battle clock off, or after an old mod refused payload 4, the outcome is payload 3 with the same army slots
    /// (the levy loss permille is filled in both, for the delivery's fallback).</summary>
    private static void OutcomePayloadV3()
    {
        var battle = Scenarios.FrankishWinterHills();
        var req = Mapper.BuildRequest(battle, new MapperOptions());
        var result = Synthetic(req, "defender");
        var v4 = Mapper.BuildOutcome(battle, req, result, new MapperOptions());
        var off = new MapperOptions();
        off.BattleClock.Enabled = false;
        var oldMod = new MapperOptions();
        oldMod.BattleClock.MaxPayloadVersion = 3;
        foreach (var options in new[] { off, oldMod })
        {
            var v3 = Mapper.BuildOutcome(battle, req, result, options);
            Expect.Equal((3, 0), (v3.PayloadVersion, v3.PaceDays));
            Expect.Equal(JsonSerializer.Serialize(v4.Armies, Json), JsonSerializer.Serialize(v3.Armies, Json));
            Expect.Equal((v4.MyLost, v4.EnemyLost, v4.MyKills, v4.PrestigeBonus, v4.Summary), (v3.MyLost, v3.EnemyLost, v3.MyKills, v3.PrestigeBonus, v3.Summary));
        }
        Expect.True(v4.Armies.All(a => a.LevyLossPermille > 0));
    }

    /// <summary>Clash 1 at Auvergne as the bridge planned and resolved it: the French win, Ekkehard (tag 24) is killed in it, Ulrich
    /// (tag 23) fell in an earlier clash (FallenTags), and the request carries coats of arms and the noon hour.</summary>
    private static ParentLink ParentClash()
    {
        var planned = Scenarios.FrankishWinterHills();
        var options = new MapperOptions();
        var req = Mapper.BuildRequest(planned, options);
        req.TimeOfDay = 12;
        req.Presentation.AttackerCoaPng = @"C:ck3xblcoaaquitaine.png";
        req.Presentation.DefenderCoaPng = @"C:ck3xblcoaswabia.png";
        var outcome = Mapper.BuildOutcome(planned, req, Synthetic(req, "attacker"), options);
