    /// <summary>The live snapshot when Welf's host reinforces the beaten Swabians four days later: a new bid, Aquitaine still at its
    /// full strength in CK3 (the steering has not inflicted the Bannerlord dead yet), the Swabian levies already below their
    /// Bannerlord survivors, and the fresh Bavarian army.</summary>
    private static BattleSnapshot ReinforcementLive(int bid, int parentBid, int clash)
    {
        var live = Scenarios.FrankishWinterHills();
        (live.Bid, live.ParentBid, live.Clash, live.Day) = (bid, parentBid, clash, 19);
        var swabia = live.Defender.Armies.Single(a => a.Tag == 21);
        swabia.Levies = 1000;
        swabia.Size = swabia.Levies + swabia.Regiments.Sum(r => r.Current);
        var welf = Scenarios.Ref(160, "Welf", "d_bavaria");
        var bavarian = Scenarios.Cul("bavarian", "heritage_central_germanic", "western_unit_gfx", Scenarios.High);
        live.Defender.Armies.Add(Scenarios.Army(25, "Host of Bavaria", welf, welf, bavarian, 1500, ("armored_footmen", 300, 300)));
        live.Defender.Characters.Add(Scenarios.Person(welf, 25, "CMD", bavarian, 12, 13, 45, 3, 25));
        live.Defender.Size = live.Defender.Armies.Sum(a => a.Size);
        return live;
    }

    private static void ContinuationCap()
    {
        var parent = ParentClash();
        var live = ReinforcementLive(7, 2, 2);
        string untouched = JsonSerializer.Serialize(live, Json);
        var capped = ContinuationSnapshot.Cap(live, parent);
        Expect.Equal(untouched, JsonSerializer.Serialize(live, Json), "the live snapshot is not changed");
        Expect.Equal((live.RequestId, 2, 2), (capped.RequestId, capped.ParentBid, capped.Clash));

        int Dead(GroupKey key) => parent.Outcome.GroupLosses.Where(g => g.GroupKey == key.ToString()).Sum(g => g.Dead);
        foreach (var before in parent.Planned.Sides.SelectMany(s => s.Armies))
        {
            var now = live.Sides.SelectMany(s => s.Armies).Single(a => a.Tag == before.Tag);
            var cap = capped.Sides.SelectMany(s => s.Armies).Single(a => a.Tag == before.Tag);
            Expect.Equal(Math.Min(now.Levies, before.Levies - Dead(GroupKey.Levy(before.Tag))), cap.Levies, $"army {before.Tag} levies");
            foreach (var reg in before.Regiments)
            {
                int current = now.Regiments.Single(r => r.RegimentId == reg.RegimentId).Current;
                Expect.Equal(Math.Min(current, reg.Current - Dead(GroupKey.Maa(reg.MaaKey, before.Tag, reg.RegimentId))),
                    cap.Regiments.Single(r => r.RegimentId == reg.RegimentId).Current, $"{reg.MaaKey}#{before.Tag}");
            }
            Expect.Equal(cap.Levies + cap.Regiments.Sum(r => r.Current), cap.Size, $"army {before.Tag} size re-summed");
        }
        var aquitaine = capped.Attacker.Armies.Single(a => a.Tag == 11);
        Expect.True(aquitaine.Levies < live.Attacker.Armies.Single(a => a.Tag == 11).Levies, "capped at its Bannerlord survivors");
        Expect.Equal(1000, capped.Defender.Armies.Single(a => a.Tag == 21).Levies, "CK3 already below the survivors: CK3's number");
        Expect.Equal(JsonSerializer.Serialize(live.Defender.Armies.Single(a => a.Tag == 25), Json),
            JsonSerializer.Serialize(capped.Defender.Armies.Single(a => a.Tag == 25), Json), "the reinforcement as logged");
        foreach (var side in capped.Sides)
        {
            var liveSide = live.Side(side.Key);
            Expect.Equal(liveSide.Size - liveSide.Armies.Sum(a => a.Size) + side.Armies.Sum(a => a.Size), side.Size, $"{side.Key} size");
        }

        // CK3 above the survivors in the levies but below them in one regiment: each group takes its own minimum.
        var mixed = ReinforcementLive(7, 2, 2);
        var thin = mixed.Attacker.Armies.Single(a => a.Tag == 11);
        thin.Regiments[0].Current = 1;
        thin.Size = thin.Levies + thin.Regiments.Sum(r => r.Current);
        mixed.Attacker.Size = mixed.Attacker.Armies.Sum(a => a.Size);
        var earlier = parent.Planned.Attacker.Armies.Single(a => a.Tag == 11);
        var mixedCap = ContinuationSnapshot.Cap(mixed, parent).Attacker.Armies.Single(a => a.Tag == 11);
        Expect.True(earlier.Regiments[0].Current - Dead(GroupKey.Maa(earlier.Regiments[0].MaaKey, 11, earlier.Regiments[0].RegimentId)) > 1);
        Expect.Equal(1, mixedCap.Regiments[0].Current, "CK3's regiment below its survivors");
        Expect.Equal(earlier.Levies - Dead(GroupKey.Levy(11)), mixedCap.Levies, "the levies at their survivors");
        foreach (var reg in earlier.Regiments.Skip(1))
            Expect.Equal(reg.Current - Dead(GroupKey.Maa(reg.MaaKey, 11, reg.RegimentId)), mixedCap.Regiments.Single(r => r.RegimentId == reg.RegimentId).Current, reg.MaaKey);
        Expect.Equal(mixedCap.Levies + mixedCap.Regiments.Sum(r => r.Current), mixedCap.Size);

        var fallen = parent.Outcome.Characters.Where(c => c.Fate >= Fates.Captured).Select(c => c.Tag).Append(23).ToHashSet();
        Expect.True(fallen.Contains(24));
        var kept = capped.Sides.SelectMany(s => s.Characters).Select(c => c.Tag).ToHashSet();
        Expect.False(kept.Overlaps(fallen), "characters captured or killed earlier are left out");
        Expect.True(live.Sides.SelectMany(s => s.Characters).Select(c => c.Tag).Where(tag => !fallen.Contains(tag)).All(kept.Contains));
    }

    private static void ContinuationRequest()
    {
        var parent = ParentClash();
        var live = ReinforcementLive(7, 2, 2);
        var options = new MapperOptions();
        var plan = Mapper.BuildContinuation(live, parent, options);
        var req = plan.Request;
        var earlier = parent.Request;
        Expect.Equal(live.RequestId, req.Id);
        Expect.Equal((earlier.Kind, earlier.Scene, earlier.Season, earlier.PlayerSide), (req.Kind, req.Scene, req.Season, req.PlayerSide));
        Expect.Equal(15f, req.TimeOfDay, "the next stock hour after noon");
        var p = req.Presentation;
        Expect.Equal(PresentationWriter.ReinforcementsTitle, p.Title);
        Expect.Equal($"Welf brings fresh troops to the Host of Konrad von Staufen · {Text.SeasonName(earlier.Season)} 1095", p.Subtitle);
        Expect.Equal((earlier.Presentation.Detail, earlier.Presentation.Deployment, earlier.Presentation.InEngineTitle), (p.Detail, p.Deployment, p.InEngineTitle));
        Expect.Equal((earlier.Presentation.AttackerCoaPng, earlier.Presentation.DefenderCoaPng), (p.AttackerCoaPng, p.DefenderCoaPng));
        Expect.True(p.Objective.StartsWith("Rout ", StringComparison.Ordinal), p.Objective);

        // Planned from the capped snapshot: the reinforcement fights, the fallen do not.
        Expect.Equal(JsonSerializer.Serialize(ContinuationSnapshot.Cap(live, parent), Json), JsonSerializer.Serialize(plan.Capped, Json));
        Expect.True(req.Defender.Troops.Any(x => x.Group == "levy#25") && req.Defender.Heroes.Any(h => h.Ck3Id == 160));
        var cappedTags = plan.Capped.Sides.SelectMany(s => s.Characters).Select(c => c.Tag).ToHashSet();
        Expect.True(req.Attacker.Heroes.Concat(req.Defender.Heroes).All(h => cappedTags.Contains(h.Tag)));
        Expect.Equal(JsonSerializer.Serialize(req, Json), JsonSerializer.Serialize(Mapper.BuildContinuation(live, parent, options).Request, Json), "deterministic");

        foreach (var (from, to) in new[] { (6f, 12f), (12f, 15f), (15f, 18f), (18f, 18f), (22f, 22f) })
        {
            earlier.TimeOfDay = from;
            Expect.Equal(to, Mapper.BuildContinuation(live, parent, options).Request.TimeOfDay, $"hour after {from}");
        }
    }

    private static void ContinuationOutcome()
    {
        var parent = ParentClash();
        var options = new MapperOptions();
        var plan = Mapper.BuildContinuation(ReinforcementLive(7, 2, 2), parent, options);
        var o = Mapper.BuildOutcome(plan.Capped, plan.Request, Synthetic(plan.Request, "attacker"), options, parent);
        Expect.Equal((7, 2, 2, 4), (o.Bid, o.ParentBid, o.Clash, o.PayloadVersion));
        Expect.Equal(parent.Outcome.AttackerKillTarget + SideDead(o, SideKey.Defender), o.AttackerKillTarget, "kill targets are cumulative");
        Expect.Equal(parent.Outcome.DefenderKillTarget + SideDead(o, SideKey.Attacker), o.DefenderKillTarget);
        Expect.Equal((parent.Outcome.MyLost + SideDead(o, SideKey.Attacker), parent.Outcome.EnemyLost + SideDead(o, SideKey.Defender), parent.Outcome.MyKills + 5),
            (o.MyLost, o.EnemyLost, o.MyKills), "r4..r6 are cumulative");
        Expect.Equal(Math.Min(200, 2 * 5) + 25, o.PrestigeBonus, "r7 is per clash");
        Expect.True(o.Summary.Contains(Text.Number(o.EnemyLost), StringComparison.Ordinal), o.Summary);

        // The end states come from the capped snapshot (Aquitaine's capped levies, not the live ones).
        ExpectSteeredEndStates(parent.Planned, plan.Capped, parent.Outcome, o);
        Expect.True(o.Armies.Any(a => a.ArmyTag == 11) && o.Armies.Any(a => a.ArmyTag == 25));

        // Clash 3 nests: its parent is clash 2, whose planned snapshot was already capped by clash 1.
        var link = new ParentLink
        {
            Planned = plan.Capped, Request = plan.Request, Outcome = o,
            FallenTags = parent.FallenTags.Concat(o.Characters.Where(c => c.Fate >= Fates.Captured).Select(c => c.Tag)).ToHashSet(),
        };
        var plan3 = Mapper.BuildContinuation(ReinforcementLive(9, 7, 3), link, options);
        int levyDead2 = o.GroupLosses.Where(g => g.GroupKey == "levy#11").Sum(g => g.Dead);
        Expect.Equal(plan.Capped.Attacker.Armies.Single(a => a.Tag == 11).Levies - levyDead2, plan3.Capped.Attacker.Armies.Single(a => a.Tag == 11).Levies);
        var o3 = Mapper.BuildOutcome(plan3.Capped, plan3.Request, Synthetic(plan3.Request, "attacker"), options, link);
        Expect.Equal((9, 7, 3), (o3.Bid, o3.ParentBid, o3.Clash));
        Expect.Equal(o.AttackerKillTarget + SideDead(o3, SideKey.Defender), o3.AttackerKillTarget);
    }

    /// <summary>A modded MaA type: resolved by its fallback base type, but outside ck3_maa_index.json.</summary>
