        var att = Scenarios.Side(SideKey.Attacker, true, me,
            new[]
            {
                Scenarios.Army(11, "Host of Toulouse", me, me, french, 0, ("armored_footmen", 300, 300), ("bowmen", 200, 200)),
                Scenarios.Army(12, "Host of Foix", vassal, vassal, french, 800, ("light_footmen", 220, 220), ("bowmen", 200, 200), ("pikemen_unit", 180, 180),
                    ("light_horsemen", 160, 160), ("armored_horsemen", 150, 150), ("crossbowmen", 140, 140), ("armored_footmen", 60, 60), (ModdedMaa, 90, 90)),
            },
            new[] { Scenarios.Person(me, 70, "CMD+PRIMARY", french, 12, 14, 40, 3, 11, player: true), Scenarios.Person(vassal, 71, "CMD", french, 9, 10, 35, 2, 12) });
        var def = Scenarios.Side(SideKey.Defender, false, konrad,
            new[] { Scenarios.Army(21, "Host of Swabia", konrad, konrad, german, 2400, ("armored_footmen", 200, 200)) },
            new[] { Scenarios.Person(konrad, 80, "CMD+PRIMARY", german, 13, 15, 50, 3, 21) });
        var battle = Scenarios.Battle(bid, "Battle of Albi", (1095, 5, 1), 2292, "Clermont", "c_auvergne", "hills", "none", "castle_holding", 3, false, false,
            "War for the Duchy of Auvergne", 170, att, def, ("region", "world_europe_west"));
        (battle.ParentBid, battle.Clash) = (parentBid, clash);
        return battle;
