    /// <summary>A Bannerlord result in which only the groups <paramref name="hit"/> selects lose men (a quarter of them killed),
    /// with every hero unharmed.</summary>
    private static BattleResult LossesOnly(BattleRequest req, string winner, Func<string, bool> hit)
    {
        var result = Synthetic(req, winner);
        foreach (var (key, g) in result.Attacker.Groups.Concat(result.Defender.Groups))
            (g.Killed, g.Wounded, g.Routed) = (hit(key) ? Math.Max(1, g.Requested / 4) : 0, 0, 0);
        foreach (var h in result.Heroes) { h.State = "alive"; h.KilledBy = null; h.Kills = 0; }
        return result;
    }

    private static int GroupDead(Ck3Outcome o, string prefix) =>
        o.GroupLosses.Where(g => g.GroupKey.StartsWith(prefix, StringComparison.Ordinal)).Sum(g => g.Dead);

    private static bool Indexed(string maaKey) => Tables.MaaIndex.ContainsKey(maaKey);

    /// <summary>The mod's fix on one army after the clashes of a steered combat (PROTOCOL §14.4): the latest slot naming
    /// the army is its end state, else its steering-start state; the levies are cut to the target (never raised), then every indexed
    /// MaA type is set to its steering-start share of max and, where the slot has a pair, to the pair. Returns the levies plus the
    /// indexed MaA men (unindexed types keep CK3's own losses).</summary>
    /// <param name="start">The army at the steering start (the first clash it fought).</param>
    /// <param name="atFix">The army in CK3 when the fix runs.</param>
    private static double SteeredFix(ArmySnapshot start, ArmySnapshot atFix, IEnumerable<Ck3Outcome> clashes)
    {
        var slot = clashes.Select(o => o.Armies.FirstOrDefault(a => a.ArmyTag == start.Tag)).LastOrDefault(a => a is not null);
        double men = Math.Min(atFix.Levies, slot?.LevySurvivors ?? start.Levies);
        foreach (var type in atFix.Regiments.Where(r => Indexed(r.MaaKey)).GroupBy(r => r.MaaKey))
        {
            double max = type.Sum(r => r.Max);
            var before = start.Regiments.Where(r => r.MaaKey == type.Key).ToList();
            double current = before.Sum(r => r.Max) > 0 ? max * before.Sum(r => r.Current) / before.Sum(r => r.Max) : type.Sum(r => r.Current);
            if (slot?.Maa.FirstOrDefault(m => m.MaaKey == type.Key) is { } pair) current = max * pair.SurvivorSharePermille / 1000.0;
            men += current;
        }
        return men;
    }

    /// <summary>After the latest clash, the mod's fix leaves every army of <paramref name="planned"/> with what fought that clash less
    /// its dead (levies and indexed MaA), up to the permille rounding: the earlier clashes' losses stay, whatever the latest slot
    /// names. CK3 is taken to hold the planned armies when the fix runs.</summary>
    /// <param name="first">The first clash's planned snapshot (the mod's steering-start state).</param>
    /// <param name="clashes">The outcomes of the clashes so far, in order.</param>
    private static void ExpectSteeredEndStates(BattleSnapshot first, BattleSnapshot planned, params Ck3Outcome[] clashes)
    {
        var last = clashes[^1];
        var start = first.Sides.SelectMany(s => s.Armies).Where(a => a.Tag > 0).ToDictionary(a => a.Tag);
        foreach (var army in planned.Sides.SelectMany(s => s.Armies).Where(a => a.Tag > 0))
        {
            int dead = last.GroupLosses.Where(g => GroupKey.TryParse(g.GroupKey, out var k) && k.ArmyTag == army.Tag
                                                   && (k.Kind == GroupKind.Levy || k.Kind == GroupKind.Maa && Indexed(k.MaaKey!))).Sum(g => g.Dead);
            double expected = army.Levies + army.Regiments.Where(r => Indexed(r.MaaKey)).Sum(r => r.Current) - dead;
            // An army new in this clash starts here, and no earlier slot names it.
            double after = start.TryGetValue(army.Tag, out var before) ? SteeredFix(before, army, clashes) : SteeredFix(army, army, new[] { last });
            double tolerance = army.Regiments.Count + 1 + army.Regiments.Sum(r => r.Max) / 2000.0;
            Expect.True(Math.Abs(after - expected) <= tolerance, $"army {army.Tag}: the fix leaves {after:0} men, Bannerlord {expected} (± {tolerance:0})");
        }
    }

    /// <summary>PROTOCOL §14.4: the mod keeps the first clash's steering-start state for every child, a slot overwrites all six
    /// pairs, and a type no pair names returns to that state. So an army of the earlier clash keeps a pair for every type, its
    /// levies give up what the restore of its folded types puts back, and an army without losses in this clash stays unlisted.</summary>
    private static void ContinuationEndStates()
    {
        var options = new MapperOptions();
        var first = SteeredCombat(30, 0, 1);
        var req1 = Mapper.BuildRequest(first, options);
        Expect.True(req1.Attacker.Troops.Any(x => x.Group!.StartsWith($"maa:{ModdedMaa}#12#", StringComparison.Ordinal)), "the modded type fights");
        var o1 = Mapper.BuildOutcome(first, req1, LossesOnly(req1, "attacker", _ => true), options);
        ExpectSteeredEndStates(first, first, o1);

        // Clash 1: the vassal's smallest indexed type is folded; its dead come out of the levies, the modded type's do not (CK3's).
        var foix1 = o1.Armies.Single(a => a.ArmyTag == 12);
        int foldedDead1 = GroupDead(o1, "maa:armored_footmen#12#"), moddedDead1 = GroupDead(o1, $"maa:{ModdedMaa}#12#");
        Expect.True(foix1.Maa.Count == OutcomeBuilder.MaaSlotsPerArmy && foix1.Maa.All(m => m.MaaKey != "armored_footmen"), string.Join(",", foix1.Maa.Select(m => m.MaaKey)));
        Expect.True(foldedDead1 > 0 && moddedDead1 > 0, $"{foldedDead1} folded, {moddedDead1} modded dead");
        Expect.Equal(800 - GroupDead(o1, "levy#12") - foldedDead1, foix1.LevySurvivors);
        Expect.Equal(JsCompat.RoundToInt(1000.0 * (GroupDead(o1, "levy#12") + foldedDead1 + moddedDead1) / (800 + 60 + 90)), foix1.LevyLossPermille, "v3 folds the modded type");

        // Clash 2: reinforcements four days later, CK3 still at full strength; only the Toulouse bowmen and the Foix levies lose men.
        var parent = new ParentLink { Planned = first, Request = req1, Outcome = o1 };
        var plan = Mapper.BuildContinuation(SteeredCombat(31, 30, 2), parent, options);
        var o2 = Mapper.BuildOutcome(plan.Capped, plan.Request, LossesOnly(plan.Request, "attacker", g => g.StartsWith("maa:bowmen#11#", StringComparison.Ordinal) || g == "levy#12"), options, parent);
        ExpectSteeredEndStates(first, plan.Capped, o1, o2);

        // The MaA-only host keeps a pair for the type that lost men in clash 1 only, at its capped strength.
        var toulouse = o2.Armies.Single(a => a.ArmyTag == 11);
        int footmen = plan.Capped.Attacker.Armies.Single(a => a.Tag == 11).Regiments.Single(r => r.MaaKey == "armored_footmen").Current;
        Expect.Equal(300 - GroupDead(o1, "maa:armored_footmen#11#"), footmen);
        Expect.True(footmen < 300);
        Expect.SequenceEqual(new[] { "armored_footmen", "bowmen" }, toulouse.Maa.Select(m => m.MaaKey).OrderBy(k => k, StringComparer.Ordinal));
        Expect.Equal(JsCompat.RoundToInt(1000.0 * footmen / 300), toulouse.Maa.Single(m => m.MaaKey == "armored_footmen").SurvivorSharePermille);

        // The folded type returns to its steering-start state, so its clash-1 dead come out of the vassal's levies again.
        var foix2 = o2.Armies.Single(a => a.ArmyTag == 12);
        var cappedFoix = plan.Capped.Attacker.Armies.Single(a => a.Tag == 12);
        Expect.Equal(cappedFoix.Levies - GroupDead(o2, "levy#12") - foldedDead1, foix2.LevySurvivors);
        Expect.Equal(OutcomeBuilder.MaaSlotsPerArmy, foix2.Maa.Count);

        // The Swabians lost nobody in this clash: unlisted, they keep their clash-1 end state.
        Expect.False(o2.Armies.Any(a => a.ArmyTag == 21));

        // Clash 3 nests on clash 2. The mod still holds the first clash's steering-start state, so the folded type returns to it once
        // more: ParentLink.Root carries that snapshot, because the parent's own planned snapshot is already capped by clash 1.
        var link = new ParentLink { Planned = plan.Capped, Request = plan.Request, Outcome = o2, Root = first };
        var plan3 = Mapper.BuildContinuation(SteeredCombat(32, 31, 3), link, options);
        BattleResult Clash3() => LossesOnly(plan3.Request, "attacker", g => g == "levy#12");
        var o3 = Mapper.BuildOutcome(plan3.Capped, plan3.Request, Clash3(), options, link);
        Expect.Equal((32, 31, 3), (o3.Bid, o3.ParentBid, o3.Clash));
        ExpectSteeredEndStates(first, plan3.Capped, o1, o2, o3);
        var foix3 = o3.Armies.Single(a => a.ArmyTag == 12);
        Expect.Equal(plan3.Capped.Attacker.Armies.Single(a => a.Tag == 12).Levies - GroupDead(o3, "levy#12") - foldedDead1, foix3.LevySurvivors,
            "clash 3 gives up the folded type's clash-1 dead again");
        link.Root = null;
        var blind = Mapper.BuildOutcome(plan3.Capped, plan3.Request, Clash3(), options, link).Armies.Single(a => a.ArmyTag == 12);
        Expect.True(blind.LevySurvivors > foix3.LevySurvivors, $"without the first clash the folded type's clash-1 dead are missed ({blind.LevySurvivors} vs {foix3.LevySurvivors})");
    }

    /// <summary>A cancelled reinforcement clash is payload 4 naming its parent with nothing to apply (the mod hands the parent back,
    /// ST|RESUME reason 4); a broken-off one applies its casualties with cumulative targets.</summary>
    private static void ContinuationCancelAndAbort()
    {
        var parent = ParentClash();
        var options = new MapperOptions();
        var plan = Mapper.BuildContinuation(ReinforcementLive(7, 2, 2), parent, options);
        var cancel = Mapper.BuildOutcome(plan.Capped, plan.Request, Synthetic(plan.Request, "attacker", "cancelled"), options, parent);
        Expect.Equal((4, 4, 2, 2), (cancel.OutcomeCode, cancel.PayloadVersion, cancel.ParentBid, cancel.Clash));
        Expect.Equal((0, 0, 0, 0), (cancel.Armies.Count, cancel.GroupLosses.Count, cancel.Characters.Count, cancel.AttackerKillTarget));

        var abort = Mapper.BuildOutcome(plan.Capped, plan.Request, Synthetic(plan.Request, "attacker", "aborted"), options, parent);
        Expect.Equal((3, 4, 2, 2), (abort.OutcomeCode, abort.PayloadVersion, abort.ParentBid, abort.Clash));
        Expect.True(SideDead(abort, SideKey.Attacker) > 0 && SideDead(abort, SideKey.Defender) > 0);
        Expect.Equal(parent.Outcome.AttackerKillTarget + SideDead(abort, SideKey.Defender), abort.AttackerKillTarget, "kill targets are cumulative");
        Expect.Equal(parent.Outcome.DefenderKillTarget + SideDead(abort, SideKey.Attacker), abort.DefenderKillTarget);
        Expect.Equal((parent.Outcome.MyLost + SideDead(abort, SideKey.Attacker), parent.Outcome.EnemyLost + SideDead(abort, SideKey.Defender)), (abort.MyLost, abort.EnemyLost));
        Expect.Equal(0, abort.PrestigeBonus, "no valour for an undecided clash");
        Expect.True(abort.Summary.StartsWith("The battle at ", StringComparison.Ordinal), abort.Summary);
        ExpectSteeredEndStates(parent.Planned, plan.Capped, parent.Outcome, abort);
    }

    /// <summary>A reinforcement clash of a mod with the knights pass: the child request gets the side and group buffs and the general's
    /// trait Tactics, and the child outcome the knights' casualty and fate factors and awards, exactly as a first clash would.</summary>
    private static void ContinuationKnights()
    {
        var options = new MapperOptions();
        var first = GateBattle();
        var req1 = Mapper.BuildRequest(first, options);
        var parent = new ParentLink { Planned = first, Request = req1, Outcome = Mapper.BuildOutcome(first, req1, Synthetic(req1, "attacker"), options) };
        BattleSnapshot Live()
        {
            var live = GateBattle();
            (live.Bid, live.ParentBid, live.Clash) = (21, first.Bid, 2);
            return live;
        }
        var plan = Mapper.BuildContinuation(Live(), parent, options);
        Expect.True(plan.Capped.KnightFactsLogged, "the cap keeps the knights facts");
        Expect.NotNull(plan.Request.Attacker.Buffs);
        Expect.True(plan.Request.Attacker.GroupBuffs.Count > 0);
        Expect.True(HeroOf(plan.Request, 1).Skills["Tactics"] > 100, "forest_fighter L3 adds Tactics to the general");

        var result = Synthetic(plan.Request, "attacker");
        var o = Mapper.BuildOutcome(plan.Capped, plan.Request, result, options, parent);
        Expect.True(o.Awards.Count > 0, "awards");
        var alone = Mapper.BuildOutcome(plan.Capped, plan.Request, result, options);
        Expect.Equal(JsonSerializer.Serialize((alone.GroupLosses, alone.Characters, alone.Awards), Json), JsonSerializer.Serialize((o.GroupLosses, o.Characters, o.Awards), Json),
            "the same knights pass as a first clash");
        var stripped = Mapper.BuildOutcome(WithoutKnightFacts(ContinuationSnapshot.Cap(Live(), parent)), plan.Request, result, options, parent);
        Expect.Equal(0, stripped.Awards.Count, "without the knights facts the child outcome has no knights pass");
    }

