    private static class Scenarios
    {
        public static readonly (string Name, Func<BattleSnapshot> Build)[] All =
        {
            ("indian_probe3", IndianProbe3), ("frankish_winter_hills", FrankishWinterHills), ("steppe_horse_archers", SteppeHorseArchers),
            ("siege_castle", SiegeCastle), ("tiny_raid", TinyRaid), ("huge", Huge),
