        internal const string Tribal = "culture_era_tribal", Early = "culture_era_early_medieval", High = "culture_era_high_medieval";

        internal static CultureInfo Cul(string key, string heritage, string gfx, string era) => new() { Culture = key, Heritage = heritage, UnitGfx = gfx, Era = era };

        internal static CharacterRef Ref(long id, string name, string? title = null) => new() { Ck3Id = id, Name = name, TitleKey = title };

        internal static CharacterSnapshot Person(CharacterRef r, int tag, string roles, CultureInfo c, int prowess, int martial, int age, int tier, int army,
            bool female = false, bool player = false, params string[] traits)
        {
            var set = roles.Split('+');
            return new CharacterSnapshot
            {
                Ref = r, Tag = tag, Role = set[0], IsCommander = set.Contains("CMD"), IsKnight = set.Contains("KNIGHT"), IsPrimary = set.Contains("PRIMARY"),
                IsPlayer = player, Culture = c, Prowess = prowess, Martial = martial, Age = age, Tier = tier, ArmyTag = army, Female = female,
                Traits = traits.ToList(),
            };
        }

        internal static ArmySnapshot Army(int tag, string name, CharacterRef owner, CharacterRef? cmd, CultureInfo c, int levies,
            params (string Maa, int Cur, int Max)[] regs)
        {
            var a = new ArmySnapshot { ArmyId = 16777000 + tag, Name = name, Tag = tag, Levies = levies, Owner = owner, Commander = cmd, OwnerCulture = c };
            for (int i = 0; i < regs.Length; i++)
                a.Regiments.Add(new RegimentSnapshot { RegimentId = 16700 + tag * 20 + i, MaaKey = regs[i].Maa, Current = regs[i].Cur, Max = regs[i].Max });
            a.Size = levies + regs.Sum(r => r.Cur);
            return a;
        }

        internal static SideSnapshot Side(SideKey key, bool playerIn, CharacterRef primary, IEnumerable<ArmySnapshot> armies, IEnumerable<CharacterSnapshot> chars)
        {
            var s = new SideSnapshot { Key = key, PlayerIn = playerIn, Primary = primary };
            s.Armies.AddRange(armies);
            s.Characters.AddRange(chars);
            s.Size = s.Armies.Sum(a => a.Size);
            return s;
        }

        internal static BattleSnapshot Battle(int bid, string combat, (int Y, int M, int D) date, long prov, string provName, string county,
            string terrain, string winter, string holding, int fort, bool siege, bool coastal, string? war, long player, SideSnapshot att, SideSnapshot def,
            params (string Key, string Value)[] extra)
        {
            var loc = new LocationInfo
            {
                ProvinceId = prov, ProvinceName = provName, CountyKey = county, Terrain = terrain, Winter = winter, Holding = holding,
                FortLevel = fort, Siege = siege, Coastal = coastal,
            };
            foreach (var (k, v) in new[] { ("terrain", terrain), ("winter", winter), ("holding", holding), ("fort", fort.ToString()),
                         ("siege", siege ? "yes" : "no"), ("coastal", coastal ? "yes" : "no") }.Concat(extra))
                loc.Facts[k] = v;
            return new BattleSnapshot
            {
                Bid = bid, SessionKey = "t3st", CombatId = 134217700 + bid, CombatName = combat, Year = date.Y, Month = date.M, Day = date.D,
                Location = loc, PlayerCk3Id = player, WarName = war, Attacker = att, Defender = def, Complete = true,
            };
        }

